    [11913]={name="Clayridge Helm",sourceType="quest_reward",instructions="Reward from the quest “A Little Help From My Friends” — pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="A Little Help From My Friends",lore="Ugh... It's so hot... I was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion."},
