    [21187]={name="Earthweave Cloak",sourceType="quest_reward",instructions="Reward from the quest “Volunteer's Battlegear” — pick it over the other choices. In Silithus.",zone="Silithus",questName="Volunteer's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them."},
