    [22784]={name="Sunwell Orb",sourceType="quest_reward",instructions="Reward from the quest “The Twin Ziggurats” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="The Twin Ziggurats",lore="These were imbued with the magical energies of the Sunwell and attuned to have warding powers against the Scourge.",proc="Use: Use on Dar'Khan Drathir to release the energy contained in this item causing 500 Arcane damage over 5 sec and silencing the target. (10 Min Cooldown)"},
    [22802]={name="Kingsfall",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [22811]={name="Soulstring",sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease"},
    [22812]={name="Nerubian Slavemaker",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [22951]={name="Springpaw Hide Leggings",sourceType="quest_reward",instructions="Reward from the quest “Pelt Collection” — pick it over the other choices. In Eversong Woods.",zone="Eversong Woods",questName="Pelt Collection",lore="The springpaw that inhabit this region are known for their high quality pelts."},
    [22954]={name="Kiss of the Spider",sourceType="boss_drop",instructions="Drops from Maexxna in Naxxramas.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs.",proc="Use: Increases your haste rating by 200 for 15 sec. (2 Min Cooldown)"},
    [22961]={name="Band of Reanimation",sourceType="boss_drop",instructions="Drops from Patchwerk in Naxxramas.",zone="Naxxramas",npc="Patchwerk",lore="An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."},
    [22979]={name="Slayer's Band",sourceType="quest_reward",instructions="Reward from the quest “Wanted: Knucklerot and Luzran” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Wanted: Knucklerot and Luzran",lore="A bounty is hereby declared for the abominations known as Knucklerot and Luzran. These dreadful creations of Dar'Khan are extremely dangerous and have been sighted patrolling near the Howling and Bleeding Ziggurats."},
    [22982]={name="Farstrider's Longbow",sourceType="quest_reward",instructions="Reward from the quest “The Traitor's Destruction” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="The Traitor's Destruction",lore="Everything we've done in the Ghostlands has been done with the goal of taking back what is rightfully ours. The Scourge have maintained their chokehold on the region for far too long."},
    [22987]={name="Deathstalker's Vest",sourceType="vendor",instructions="Bought from Provisioner Vredigar in Tranquillien.",zone="Tranquillien",npc="Provisioner Vredigar"},
    [22992]={name="Bogwalker Boots",sourceType="vendor",instructions="Bought from Provisioner Vredigar in Tranquillien.",zone="Tranquillien",npc="Provisioner Vredigar"},
    [23038]={name="Band of Unnatural Forces",sourceType="boss_drop",instructions="Drops from Loatheb in Naxxramas.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."},
    [23039]={name="The Eye of Nerub",sourceType="boss_drop",instructions="Drops from Loatheb in Naxxramas.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."},
    [23044]={name="Harbinger of Doom",sourceType="world_drop",instructions="World drop — drops from 32 creature types around level 60-63. Also found on the auction house."},
    [23045]={name="Shroud of Dominion",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."},
    [23053]={name="Stormrage's Talisman of Seething",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23067]={name="Ring of the Cryptstalker",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23071]={name="Leggings of Apocalypse",sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease"},
    [23206]={name="Mark of the Champion",sourceType="quest_reward",instructions="Reward from the quest “The Fall of Kel'Thuzad” — pick it over the other choices. In Naxxramas.",zone="Naxxramas",questName="The Fall of Kel'Thuzad",lore="Struck for the war against the Scourge and the Old Gods. It does nothing at all against anything else, which is the point of the mark."},
    [23242]={name="Claw of the Frost Wyrm",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."},
    [23323]={name="Crown of the Fire Festival",sourceType="quest_reward",instructions="Reward from the quest “A Thief's Reward”.",questName="A Thief's Reward",seasonal=true,lore="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more..."},
    [23324]={name="Mantle of the Fire Festival",sourceType="quest_reward",instructions="Reward from the quest “Wild Fires in the Eastern Kingdoms”.",questName="Wild Fires in the Eastern Kingdoms",seasonal=true,lore="Our celebration of the flame is spread throughout the land. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue."},
    [23404]={name="Padded Running Shoes",sourceType="quest_reward",instructions="Reward from the quest “Windrunner Village” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Windrunner Village",lore="the final battle against the Ghostlands villages is upon you. Windrunner Village to the southwest has been overrun by a large force of the more powerful Scourge shocktroopers; shades and gargoyles."},
    [23405]={name="Farstrider's Tunic",sourceType="quest_reward",instructions="Reward from the quest “Report to Captain Helios” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Report to Captain Helios",lore="I need one last favor of you. Just in case Ranger Salissa didn't make it back to Farstrider Enclave on the south edge of the lake, I need you to go there and get help."},
    [23408]={name="Farstrider's Bracers",sourceType="quest_reward",instructions="Reward from the quest “Assault on Zeb'Nowa” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Assault on Zeb'Nowa",lore="Time for something a little more challenging. Zeb'Nowa, to the south, is where the more powerful Shadowpine trolls make their home."},
    [23409]={name="Well Crafted Long Bow",sourceType="quest_reward",instructions="Reward from the quest “Bring Me Kel'gash's Head!” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Bring Me Kel'gash's Head!",lore="WANTED: Bring the head of Kel'gash the Wicked, chieftain of the Shadowpine trolls, to Captain Helios. No questions asked. Kel'gash is known to dwell somewhere to the south in Zeb'Nowa."},
    [23414]={name="Troll Kickers",sourceType="quest_reward",instructions="Reward from the quest “Escape from the Catacombs” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Escape from the Catacombs",lore="These trolls ambushed me and have been keeping me in this cage. I think they're planning to sacrifice me! Help me get out of here! The lock on the cage isn't that complex..."},
    [23557]={name="Larvae of the Great Worm",sourceType="boss_drop",instructions="Drops from Ouro.",npc="Ouro",lore="A sandworm grown enormous under the desert, surfacing only to feed."},
    [23844]={name="Nolkai's Lantern",sourceType="container",instructions="Found inside another item."},
    [24109]={name="Thick Ravager Belt",sourceType="quest_reward",instructions="Reward from the quest “Beasts of the Apocalypse!” — pick it over the other choices. In Azuremyst Isle.",zone="Azuremyst Isle",questName="Beasts of the Apocalypse!",lore="My brother and I were hunting in the woods to the east when we were ambushed by strange, insect-like beasts. Such aberrations have never before been seen in Azuremyst!"},
    [24111]={name="Kurken Hide Jerkin",sourceType="quest_reward",instructions="Reward from the quest “The Kurken's Hide” — pick it over the other choices. In Azuremyst Isle.",zone="Azuremyst Isle",questName="The Kurken's Hide",lore="Take the Kurken's hide to Moordo, on the other side of the village."},
    [24112]={name="Kurkenstoks",sourceType="quest_reward",instructions="Reward from the quest “The Kurken's Hide” — pick it over the other choices. In Azuremyst Isle.",zone="Azuremyst Isle",questName="The Kurken's Hide",lore="Take the Kurken's hide to Moordo, on the other side of the village. He will fashion the hide into an item of your choice."},
    [24113]={name="Cowlen's Bracers of Kinship",sourceType="quest_reward",instructions="Reward from the quest “A Cry For Help”. In Azuremyst Isle.",zone="Azuremyst Isle",questName="A Cry For Help",lore="My family was attacked by the murlocs and owlkin of this island several weeks ago. I managed to escape but I think that both my mother and father have been slain."},
    [24118]={name="Signet of Argas",sourceType="quest_reward",instructions="Reward from the quest “Never Again!” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Never Again!",lore="it falls to you to see that this attack by the Burning Legion never comes to pass. You must go and slay their leaders. Without them the rest of the demons are essentially mindless."},
    [24138]={name="Silver Crossbow",sourceType="quest_reward",instructions="Reward from the quest “Beast Training”.",questName="Beast Training",lore="Oh, one more thing! You'll want to speak with Ganaar at the Exodar. He'll be able to teach you the last bits of knowledge necessary to care for your pet and train it."},
    [24347]={name="Vest of the Dragon Slayer",sourceType="quest_reward",instructions="Reward from the quest “Razormaw” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Razormaw",lore="Many of the black dragonflight were slain during the attacks. One of them, a lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, you can see his spectral countenance circling the skies."},
    [24349]={name="Signet Ring of the Hand",sourceType="quest_reward",instructions="Reward from the quest “The Unwritten Prophecy” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="The Unwritten Prophecy"},
    [24360]={name="Tracker's Belt",sourceType="boss_drop",instructions="Drops from Mennu the Betrayer in The Slave Pens.",zone="The Slave Pens",npc="Mennu the Betrayer"},
    [24396]={name="Vest of Vengeance",sourceType="boss_drop",instructions="Drops from Keli'dan the Breaker in The Blood Furnace.",zone="The Blood Furnace",npc="Keli'dan the Breaker"},
    [24398]={name="Mantle of the Dusk-Dweller",sourceType="boss_drop",instructions="Drops from Keli'dan the Breaker in The Blood Furnace.",zone="The Blood Furnace",npc="Keli'dan the Breaker"},
    [24433]={name="Crossbow of the Albatross",sourceType="quest_reward",instructions="Reward from the quest “Show Gnomercy” — pick it over the other choices. In Azuremyst Isle.",zone="Azuremyst Isle",questName="Show Gnomercy",lore="Spark must be brought to justice! I need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him!"},
    [24439]={name="Savage Leggings",sourceType="quest_reward",instructions="Reward from the quest “Gurf's Dignity” — pick it over the other choices. In Azuremyst Isle.",zone="Azuremyst Isle",questName="Gurf's Dignity",lore="You recover the piece of fur that Gurf had \"lost\" in his struggle with the murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been slain."},
    [24441]={name="Exodar Crossbow",sourceType="quest_reward",instructions="Reward from the quest “Blood Elf Spy” — pick it over the other choices. In Ammen Vale.",zone="Ammen Vale",questName="Blood Elf Spy",lore="I have a plan. We must kill their leader. Without their master, perhaps they will retreat to regroup. We just need to buy time until the repairs are completed."},
    [25240]={name="Azerothian Longbow",sourceType="world_drop",instructions="World drop — drops from 58 creature types around level 57-68. Also found on the auction house."},
    [25241]={name="Ashenvale Longbow",sourceType="world_drop",instructions="World drop — drops from 110 creature types around level 58-68. Also found on the auction house."},
    [25242]={name="Telaari Longbow",sourceType="world_drop",instructions="World drop — drops from 176 creature types around level 59-68. Also found on the auction house."},
    [25254]={name="Tower Crossbow",sourceType="world_drop",instructions="World drop — drops from 58 creature types around level 57-68. Also found on the auction house."},
    [25255]={name="Ram's Head Crossbow",sourceType="world_drop",instructions="World drop — drops from 110 creature types around level 58-68. Also found on the auction house."},
    [25256]={name="Stronghold Crossbow",sourceType="world_drop",instructions="World drop — drops from 176 creature types around level 59-68. Also found on the auction house."},
    [25268]={name="Lead-Slug Shotgun",sourceType="world_drop",instructions="World drop — drops from 58 creature types around level 57-68. Also found on the auction house."},
    [25269]={name="Longbeard Rifle",sourceType="world_drop",instructions="World drop — drops from 110 creature types around level 58-68. Also found on the auction house."},
    [25270]={name="Gnomish Assault Rifle",sourceType="world_drop",instructions="World drop — drops from 176 creature types around level 59-68. Also found on the auction house."},
    [25438]={name="Malachite Pendant",sourceType="profession",instructions="Crafted with Jewelcrafting (requires skill 1).",profession="Jewelcrafting"},
    [25512]={name="Tribal Hauberk",sourceType="quest_reward",instructions="Reward from the quest “Envoy to the Mag'har” — pick it over the other choices. In Hellfire Peninsula.",zone="Hellfire Peninsula",questName="Envoy to the Mag'har",lore="I'd leave for Outland this very minute after hearing the news you brought. Important matters require my attention in Durotar, however. I will arrange for a fitting tribute to be sent to the Mag'har immediately."},
    [25605]={name="Burning Blade Devotee's Cinch",sourceType="quest_reward",instructions="Reward from the quest “Message to Telaar” — pick it over the other choices. In Nagrand.",zone="Nagrand",questName="Message to Telaar",lore="You have single-handedly saved my clan from extermination. You may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace."},
    [25609]={name="Burning Blade Devotee's Cinch",sourceType="quest_reward",instructions="Reward from the quest “Message to Garadar” — pick it over the other choices. In Nagrand.",zone="Nagrand",questName="Message to Garadar",lore="You have single-handedly saved my clan from extermination. You may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace."},
    [25639]={name="Hemet's Elekk Gun",sourceType="quest_reward",instructions="Reward from the quest “The Ultimate Bloodsport” — pick it over the other choices. In Nagrand.",zone="Nagrand",questName="The Ultimate Bloodsport",lore="The queen of all that dwell in Nagrand is known as Tusker. She's a giant elekk the likes of which you won't see anywhere else!"},
    [25685]={name="Fel Leather Gloves",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [25686]={name="Fel Leather Boots",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [25687]={name="Fel Leather Leggings",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [25782]={name="Sunstrider Legguards",sourceType="quest_reward",instructions="Reward from the quest “A Pilgrim's Plight” — pick it over the other choices. In Hellfire Peninsula.",zone="Hellfire Peninsula",questName="A Pilgrim's Plight",seasonal=true,lore="That wounded pilgrim seems to be shouting something about a pack. When you encountered her, did you see a pack nearby? Hmm... She must've left it when fleeing from her attackers."},
    [25789]={name="Rune-Engraved Belt",sourceType="quest_reward",instructions="Reward from the quest “Fel Embers” — pick it over the other choices. In Hellfire Citadel.",zone="Hellfire Citadel",questName="Fel Embers",lore="The stuffy academics of Azeroth have cowered in their towers for too long and it's fallen to me to show them what cutting edge research is!"},
    [25790]={name="Expedition Scout's Epaulets",sourceType="quest_reward",instructions="Reward from the quest “Fel Embers” — pick it over the other choices. In Hellfire Citadel.",zone="Hellfire Citadel",questName="Fel Embers",lore="The stuffy academics of Azeroth have cowered in their towers for too long and it's fallen to me to show them what cutting edge research is!"},
    [25927]={name="Consortium Cloak of the Quick",sourceType="quest_reward",instructions="Reward from the quest “A Personal Favor” — pick it over the other choices. In Terokkar Forest.",zone="Terokkar Forest",questName="A Personal Favor",lore="Hmmm? A box you say? Or was it several? Do you know what material the box was constructed from? And what was the name of this merchant? Empoor?"},
    [25932]={name="Cenarion Thicket Jerkin",sourceType="quest_reward",instructions="Reward from the quest “Letting Earthbinder Tavgren Know” — pick it over the other choices. In Terokkar Forest.",zone="Terokkar Forest",questName="Letting Earthbinder Tavgren Know",lore="after you're done celebrating here, I think that you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren."},
    [25937]={name="Terokkar Tablet of Precision",sourceType="quest_reward",instructions="Reward from the quest “Torgos!” — pick it over the other choices. In Terokkar Forest.",zone="Terokkar Forest",questName="Torgos!",lore="There's a creature in the Bone Wastes so fearsome that only the dauntless dare to stalk him. I speak of Torgos, king of the bonelashers, who circles over Veil Rhaze on the western edge of the wastes.",proc="Use: Increases attack power by 140 for 15 sec. (1 Min, 30 Sec Cooldown)"},
    [25951]={name="Fleet Refugee's Boots",sourceType="quest_reward",instructions="Reward from the quest “Helping the Lost Find Their Way” — pick it over the other choices. In Terokkar Forest.",zone="Terokkar Forest",questName="Helping the Lost Find Their Way",lore="Many spirits of the draenei were corrupted by the explosion of Auchindoun. Now they wander the wastes in torment., I beseech you to put them to rest."},
    [25952]={name="Scimitar of the Nexus-Stalkers",sourceType="boss_drop",instructions="Drops from Tavarok in Mana-Tombs.",zone="Mana-Tombs",npc="Tavarok"},
    [25962]={name="Longstrider's Loop",sourceType="boss_drop",instructions="Drops from Nexus-Prince Shaffar in Mana-Tombs.",zone="Mana-Tombs",npc="Nexus-Prince Shaffar"},
    [25965]={name="Cloak of Grasping Talons",sourceType="quest_reward",instructions="Reward from the quest “BETA The Final Reagents” — pick it over the other choices. In Terokkar Forest.",zone="Terokkar Forest",questName="BETA The Final Reagents",lore="I can create an item that will neutralize the ward spells protecting Veil Shalas, but be warned. The magic will only work as long as your friend is held captive."},
    [25984]={name="Miner's Brace",sourceType="quest_reward",instructions="Reward from the quest “The Mastermind” — pick it over the other choices. In Hellfire Peninsula.",zone="Hellfire Peninsula",questName="The Mastermind",lore="Those infernal gan'arg keep scurrying into the mine! For each one you kill, two or three more seem to take its place! There's got to be someone down there in the deepest reaches of the mine directing the incursion."},
    [26012]={name="Kessel's Cinch Wrap",sourceType="quest_reward",instructions="Reward from the quest “Declaration of Power” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Declaration of Power",lore="Have you seen the serpent men? The ones that call themselves naga? They dared make an advance upon this camp under cover of darkness only three nights ago."},
    [26014]={name="Maatparm's Fungus Lined Cuffs",sourceType="quest_reward",instructions="Reward from the quest “Mac'Aree Mushroom Menagerie” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Mac'Aree Mushroom Menagerie",lore="I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn, a blood mushroom, a ruinous polyspore, and a fel cone fungus."},
    [26020]={name="Shard-Covered Leggings",sourceType="quest_reward",instructions="Reward from the quest “Learning from the Crystals” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Learning from the Crystals",lore="Welcome to Blood Watch. Seeing to the defenses of the outpost is my primary concern, but I've also been tasked with a variety of other duties by our leaders at the Exodar."},
    [26021]={name="Vindicator's Leather Chaps",sourceType="quest_reward",instructions="Reward from the quest “Matis the Cruel” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Matis the Cruel",lore="Matis will be brought to justice,; and I want you to be the one to find him and bring him back to the Triumvirate. Scour the island for this bastard."},
    [26023]={name="Ravager Hide Gloves",sourceType="quest_reward",instructions="Reward from the quest “Clearing the Way” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Clearing the Way",lore="Only the most battle hardened, noble and positively fearless of draenei will submit to Legoso's mission. The exarch will not order any agent of the Hand to take on the task of destroying the Vector Coil and dispatching Sironas."},
    [26025]={name="Technician's Boots",sourceType="quest_reward",instructions="Reward from the quest “Galaen's Fate” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Galaen's Fate",lore="You have no means of identifying the corpse as Galaen with the information Morae gave you, but the clothing appears to have been torn in search of valuables."},
    [26028]={name="Maatparm's Fungus Lined Bands",sourceType="quest_reward",instructions="Reward from the quest “Mac'Aree Mushroom Menagerie” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Mac'Aree Mushroom Menagerie",lore="I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn, a blood mushroom, a ruinous polyspore, and a fel cone fungus."},
    [27389]={name="Surplus Bastard Sword",sourceType="quest_reward",instructions="Reward from the quest “Alien Predators” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Alien Predators",lore="One thing we've learned in our travels is that extreme care must be taken when introducing wildlife from one world to another."},
    [27398]={name="Carved Crystalline Orb",sourceType="quest_reward",instructions="Reward from the quest “WANTED: Deathclaw” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="WANTED: Deathclaw",lore="By order of Harbinger Mikolaas: A bounty of 18 silver to be paid to the brave soul who returns with proof of the marauding bear Deathclaw's demise."},
    [27401]={name="Arugoo's Crossbow of Destruction",sourceType="quest_reward",instructions="Reward from the quest “The Prophecy of Akida” — pick it over the other choices. In Azuremyst Isle.",zone="Azuremyst Isle",questName="The Prophecy of Akida",lore="The images on this totem depict a war between the Stillpine and the Bristlelimb furbolg tribes. The etchings show that the Bristlelimb have done unconscionable things to the furbolgs of Stillpine."},
    [27402]={name="Huntsman's Crossbow",sourceType="quest_reward",instructions="Reward from the quest “Containing the Threat” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Containing the Threat",lore="Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion's hounds in these lands."},
    [27415]={name="Darkguard Face Mask",sourceType="boss_drop",instructions="Drops from Exarch Maladaar in Auchenai Crypts.",zone="Auchenai Crypts",npc="Exarch Maladaar"},
    [27434]={name="Mantle of Perenolde",sourceType="boss_drop",instructions="Drops from Epoch Hunter.",npc="Epoch Hunter"},
    [27526]={name="Skyfire Hawk-Bow",sourceType="boss_drop",instructions="Drops from Warbringer O'mrogg in The Shattered Halls.",zone="The Shattered Halls",npc="Warbringer O'mrogg"},
    [27640]={name="Hand of Argus Crossfire",sourceType="quest_reward",instructions="Reward from the quest “Blood Watch” — pick it over the other choices. In Bloodmyst Isle.",zone="Bloodmyst Isle",questName="Blood Watch",lore="Blood Watch is one of two forward bases operated by the Hand of Argus."},
    [27722]={name="Gloves of Marshmanship",sourceType="quest_reward",instructions="Reward from the quest “Leader of the Bloodscale” — pick it over the other choices. In Zangarmarsh.",zone="Zangarmarsh",questName="Leader of the Bloodscale",lore="A bounty is hereby declared by the Cenarion Expedition on Rajis Fyashe, leader of the Bloodscale naga. The naga sorceress was last sighted at Serpent Lake, in the northern region of Zangarmarsh."},
    [27749]={name="Staff of the Wild",sourceType="quest_reward",instructions="Reward from the quest “Now That We're Friends...” — pick it over the other choices. In Zangarmarsh.",zone="Zangarmarsh",questName="Now That We're Friends...",lore="The naga of the Bloodscale Enclave to the northeast have begun to kill our people. We cannot allow this to continue! We suggest that you teach them a lesson as proof of our friendship."},
    [27794]={name="Recoilless Rocket Ripper X-54",sourceType="boss_drop",instructions="Drops from Mekgineer Steamrigger in The Steamvault.",zone="The Steamvault",npc="Mekgineer Steamrigger"},
    [27892]={name="Cloak of the Inciter",sourceType="boss_drop",instructions="Drops from Blackheart the Inciter in Shadow Labyrinth.",zone="Shadow Labyrinth",npc="Blackheart the Inciter"},
    [27925]={name="Ravenclaw Band",sourceType="boss_drop",instructions="Drops from Talon King Ikiss in Sethekk Halls.",zone="Sethekk Halls",npc="Talon King Ikiss"},
    [27995]={name="Sun-Gilded Shouldercaps",sourceType="boss_drop",instructions="Drops from Chrono Lord Deja.",npc="Chrono Lord Deja"},
    [28031]={name="Nomad's Woven Cloak",sourceType="quest_reward",instructions="Reward from the quest “Bring Me The Egg!” — pick it over the other choices. In Nagrand.",zone="Nagrand",questName="Bring Me The Egg!",lore="Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump."},
    [28032]={name="Delicate Green Poncho",sourceType="quest_reward",instructions="Reward from the quest “Bring Me The Egg!” — pick it over the other choices. In Nagrand.",zone="Nagrand",questName="Bring Me The Egg!",lore="Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump."},
    [28142]={name="Farstrider's Belt",sourceType="quest_reward",instructions="Reward from the quest “Curbing the Plague” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Curbing the Plague",lore="You've proven your worth as an ally. I need you to continue your task and track down more plagued wildlife. This time seek out some of the more dangerous beasts."},
    [28144]={name="Troll Handler Gloves",sourceType="quest_reward",instructions="Reward from the quest “Report to Captain Helios” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Report to Captain Helios",lore="I need one last favor of you. Just in case Ranger Salissa didn't make it back to Farstrider Enclave on the south edge of the lake, I need you to go there and get help."},
    [28146]={name="Courier's Wraps",sourceType="quest_reward",instructions="Reward from the quest “Delivery to Tranquillien” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Delivery to Tranquillien",lore="I... I'm too weak to continue. I carry a dire warning from Regent Lord Theron, in the form of a letter. You'll have to deliver it for me. Take it to Arcanist Vandril in Tranquillien."},
    [28147]={name="Tranquillien Scout's Bracers",sourceType="quest_reward",instructions="Reward from the quest “Delivery to Tranquillien” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Delivery to Tranquillien",lore="You'll have to deliver it for me. Take it to Arcanist Vandril in Tranquillien."},
    [28149]={name="Tranquillien Breeches",sourceType="quest_reward",instructions="Reward from the quest “Anok'suten” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Anok'suten",lore="Come closer, I am... dying. I was sent here... to slay these nerubians, but Vandril didn't... know that they have a leader. You must find and..."},
    [28158]={name="Batskin Belt",sourceType="vendor",instructions="Bought from Provisioner Vredigar in Tranquillien.",zone="Tranquillien",npc="Provisioner Vredigar"},
    [28159]={name="Undertaker's Gloves",sourceType="quest_reward",instructions="Reward from the quest “Troll Juju” — pick it over the other choices. In Ghostlands.",zone="Ghostlands",questName="Troll Juju",lore="The corpses of trolls buried inside the Amani Catacombs have been rising from the dead! I want you to go there and bring back proof of their final demise."},
    [28168]={name="Insignia of the Mag'hari Hero",sourceType="quest_reward",instructions="Reward from the quest “Hero of the Mag'har”. In Nagrand.",zone="Nagrand",questName="Hero of the Mag'har",lore="I must set things in order before I leave. Return to the Greatmother and tell her that her grandson comes."},
    [29108]={name="Blade of the Unyielding",sourceType="quest_reward",instructions="Reward from the quest “Honor the Fallen” — pick it over the other choices. In Hellfire Peninsula.",zone="Hellfire Peninsula",questName="Honor the Fallen",lore="One can never tell with spirits such as these. The Unyielding are still against us and will no doubt kill you if they can."},
    [29158]={name="Truesilver Commander's Ring",sourceType="profession",instructions="Crafted with Jewelcrafting (requires skill 1).",profession="Jewelcrafting"},
    [29391]={name="Pulse Dagger",sourceType="vendor",instructions="Bought from Dealer Jadyan in The Stormspire.",zone="The Stormspire",npc="Dealer Jadyan"},
    [29914]={name="Hellfire Skiver",sourceType="quest_reward",instructions="Reward from the quest “Bonechewer Blood” — pick it over the other choices. In Hellfire Peninsula.",zone="Hellfire Peninsula",questName="Bonechewer Blood",lore="Bonechewers! They should all die! The sight of their red skin and depravity makes my blood boil! I have a mission for you. Kill bonechewer orcs and collect their vile blood."},
    [29964]={name="Blackstorm Leggings",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [29968]={name="Nether Leggings",sourceType="quest_reward",instructions="Reward from the quest “Dr. Boom!” — pick it over the other choices. In Netherstorm.",zone="Netherstorm",questName="Dr. Boom!",lore="my former protege, Sparky Uberthruster, wouldn't wear his helmet while down here and one day transformed into the infamous Dr. Boom! And he stole off to the northeast with most of our sapping equipment!"},
    [29973]={name="Primalstorm Breastplate",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [30009]={name="The Burning Crusader",sourceType="quest_reward",instructions="Reward from the quest “Nexus-King Salhadaar” — pick it over the other choices. In Netherstorm.",zone="Netherstorm",questName="Nexus-King Salhadaar",lore="I have in my possession another disruptor, one capable of destroying the three conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar's protective force fields will be down."},
    [30010]={name="Fleshling Simulation Staff",sourceType="quest_reward",instructions="Reward from the quest “Nexus-King Salhadaar” — pick it over the other choices. In Netherstorm.",zone="Netherstorm",questName="Nexus-King Salhadaar",lore="I have in my possession another disruptor, one capable of destroying the three conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar's protective force fields will be down."},
    [30072]={name="Light Skyforged Axe",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [30077]={name="Windforged Rapier",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [30272]={name="Eco-Dome Leggings",sourceType="quest_reward",instructions="Reward from the quest “Rightful Repossession” — pick it over the other choices. In Netherstorm.",zone="Netherstorm",questName="Rightful Repossession",lore="Our business relations with the blood elves appear to be at an end. A few weeks ago a large shipment of surveying equipment was delivered to them at Manaforge Duro."},
    [30328]={name="Protectorate Assassin's Tunic",sourceType="quest_reward",instructions="Reward from the quest “Arconus the Insatiable” — pick it over the other choices. In Netherstorm.",zone="Netherstorm",questName="Arconus the Insatiable",lore="Araxes and I were deployed to Ultris 2 days ago. Our mission: Find and terminate the void lord Arconus. We tracked him to this mine and discovered that he'd been feeding off the energies of the creatures in the area."},
    [30372]={name="Socrethar's Girdle",sourceType="quest_reward",instructions="Reward from the quest “Turning Point” — pick it over the other choices. In Netherstorm.",zone="Netherstorm",questName="Turning Point",lore="This is the chance we've been waiting for. Not only have we uncovered the evidence we need to show our people who Kael'thas is really working for, but we can prove our strength by defeating his new masters."},
    [30419]={name="Brilliant Necklace",sourceType="profession",instructions="Crafted with Jewelcrafting (requires skill 1).",profession="Jewelcrafting"},
    [30420]={name="Heavy Jade Ring",sourceType="profession",instructions="Crafted with Jewelcrafting (requires skill 1).",profession="Jewelcrafting"},
    [31131]={name="Sash of Silent Blades",sourceType="world_drop",instructions="World drop — drops from 113 creature types around level 57-68. Also found on the auction house."},
    [31148]={name="Demon Hide Spaulders",sourceType="world_drop",instructions="World drop — drops from 227 creature types around level 60-63. Also found on the auction house."},
    [31255]={name="Cloak of the Craft",sourceType="world_drop",instructions="World drop — drops from 286 creature types around level 64-70. Also found on the auction house."},
    [31275]={name="Necklace of Trophies",sourceType="world_drop",instructions="World drop — drops from 370 creature types around level 65-70. Also found on the auction house."},
    [31286]={name="Breastplate of Rapid Striking",sourceType="world_drop",instructions="World drop — drops from 404 creature types around level 65-70. Also found on the auction house."},
    [31288]={name="The Master's Treads",sourceType="world_drop",instructions="World drop — drops from 404 creature types around level 65-70. Also found on the auction house."},
    [31426]={name="Agile Mountain Bracers",sourceType="quest_reward",instructions="Reward from the quest “The Bladespire Ogres” — pick it over the other choices. In Blade's Edge Mountains.",zone="Blade's Edge Mountains",questName="The Bladespire Ogres",lore="To the north of the Bloodmaul clan lies a threat more grave: Bladespire Hold. The Bladespire ogres are the strongest clan in the mountains, having the favor of the gronn known as Gruul the Dragonkiller, and his seven sons."},
    [31545]={name="Oilcloth Breeches",sourceType="quest_reward",instructions="Reward from the quest “Showdown” — pick it over the other choices. In Blade's Edge Mountains.",zone="Blade's Edge Mountains",questName="Showdown",lore="Now it comes to this. We will bring Goc forth from his lair, and we will destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer."},
    [31695]={name="Natasha's Choker",sourceType="quest_reward",instructions="Reward from the quest “The Hound-Master” — pick it over the other choices. In Blade's Edge Mountains.",zone="Blade's Edge Mountains",questName="The Hound-Master",lore="Baelmon the Hound-Master must die! He maintains the ritual that keeps the portal functioning. The Death's Door portal is located at the north end of the canyon."},
    [32474]={name="Surestrike Goggles v2.0",sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering",proc="Use: Allows you to look far into the distance. (3 Sec Cooldown)"},
    [32478]={name="Deathblow X11 Goggles",sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering",proc="Use: Allows you to look far into the distance. (3 Sec Cooldown)"},
    [33243]={name="Skirmisher's Cover",sourceType="quest_reward",instructions="Reward from the quest “Peace at Last” — pick it over the other choices. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Peace at Last",lore="I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice. There are some who say that their spirits will know, even if we cannot reach them."},
    [33245]={name="Grimsby's Gaudy Girdle",sourceType="quest_reward",instructions="Reward from the quest “Cleansing Witch Hill” — pick it over the other choices. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Cleansing Witch Hill",lore="The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth. I have no idea what the torch's smoke may reveal..."},
    [33247]={name="Swift Wind Spaulders",sourceType="quest_reward",instructions="Reward from the quest “Take Down Tethyr!” — pick it over the other choices. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Take Down Tethyr!",lore="Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr."},
    [33250]={name="Archer's Wristguard",sourceType="quest_reward",instructions="Reward from the quest “Return to Jaina” — pick it over the other choices. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Return to Jaina",lore="The ogres here are useful for little more than crude jokes, sour ale, and bouts of headbutting. When my ship, the Dawn Runner, ran aground, those curs from Theramore made off with my cargo and last surviving crewman."},
    [34417]={name="Marauder's Handwraps",sourceType="quest_reward",instructions="Reward from the quest “Rise of the Silithid” — pick it over the other choices. In Feralas.",zone="Feralas",questName="Rise of the Silithid",lore="I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas. While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate."},
    [34421]={name="Cave Crawler's Mail Treads",sourceType="quest_reward",instructions="Reward from the quest “A Future Task” — pick it over the other choices. In Thunder Bluff.",zone="Thunder Bluff",questName="A Future Task",lore="Well... we seem to be at an unfortunate impasse. We know what we need - the Plates of Uldum - but we have no idea where they might be. We will research this, and then devise a solid plan of attack."},
    [34423]={name="Strength of the High Chief",sourceType="quest_reward",instructions="Reward from the quest “Words of the High Chief” — pick it over the other choices. In Winterspring.",zone="Winterspring",questName="Words of the High Chief",lore="The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper."},
}

